def solve(records):
    from collections import defaultdict
    graph = defaultdict(list)
    splits = {}
    for key, split, family, parents in records:
        if not isinstance(key, str) or not key or not isinstance(family, str) or not family or key in splits or split not in ("train", "eval"):
            raise ValueError("invalid record")
        splits[key] = split
    for key, split, family, parents in records:
        hub = ("family", family)
        if any(parent not in splits for parent in parents):
            raise ValueError("unknown parent")
        for peer in [hub, *parents]:
            graph[key].append(peer)
            graph[peer].append(key)
    seen = {key for key, split in splits.items() if split == "eval"}
    pending = list(seen)
    while pending:
        for peer in graph[pending.pop()]:
            if peer not in seen:
                seen.add(peer)
                pending.append(peer)
    return sorted(key for key, split in splits.items() if split == "train" and key in seen)
